            FileUtils.class.getDeclaredMethod("checkFileExists", File.class, String.class)
                .setAccessible(true);
            FileUtils.class.getDeclaredMethod("checkFileExists", File.class, String.class)
                .invoke(null, nonExistentFile, "nonExistentFile");
        });
    }
}

